using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Creates a new call
    /// </summary>
    public Task<TdLib.TdApi.Objects.CallId> CreateCallAsync(long userId = default, CallProtocol protocol = default, bool isVideo = default)
    {

           using var activity =  StartCallActivity("CreateCallAsync", typeof(CreateCall).FullName ?? "CreateCallAsync");

           try
           {
             return client.CreateCallAsync(userId, protocol, isVideo);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
